    `=IF(OR(G${r}="REVIEW",H${r}="REVIEW",I${r}="REVIEW",J${r}="REVIEW",M${r}<>"",N${r}<>""),"REVIEW","OK")`
  ];
}

function parkKey(c) {
  return String.raw`REGEXREPLACE(REGEXREPLACE(REGEXREPLACE(REGEXREPLACE(REGEXREPLACE(REGEXREPLACE(REGEXREPLACE(LOWER(${c}),"\bw\b","west"),"\be\b","east"),"\bn\b","north"),"\bs\b","south"),"pk\b","park"),"boro\b","borough"),"[^a-z]","")`;
}

// ============================= THEME CODER =============================

/** True if any data row in the text column has a non-empty response. */
function hasTextResponses_(sh, last) {
  if (last < 2) return false;
  const vals = sh.getRange(2, CONFIG.textCol, last - 1, 1).getValues();
  return vals.some(([v]) => String(v).trim() !== "");
}

/** Escapes regex special characters in a keyword. */
function escapeRegex_(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Builds { theme: [RegExp, ...] } with word boundaries and common suffixes. */
function buildThemePatterns_(mapping) {
  const patterns = {};
  Object.keys(mapping).forEach(theme => {
    patterns[theme] = mapping[theme].map(kw => {
      const k = escapeRegex_(String(kw).trim().toLowerCase());
      return new RegExp("\\b" + k + "(?:s|es|ed|ing|ly|er|ers)?\\b");
    });
  });
  return patterns;
}

/** Returns sorted, deduped, lowercase theme tags for one response, or "" if blank. */
function tagThemes_(text, patterns) {
  const t = String(text || "").trim().toLowerCase();
  if (!t) return "";
  const found = new Set();
  Object.keys(patterns).forEach(theme => {
    if (patterns[theme].some(re => re.test(t))) found.add(theme.toLowerCase());
  });
  if (found.size === 0) return CONFIG.otherLabel;
  return [...found].sort().join(", ");
}

/** Returns [startRow, endRow] from the selection on sh, or the full data range. */
function targetRows_(ss, sh, last) {
  const full = [2, last];
  const active = ss.getActiveRange();
  if (!active || active.getSheet().getSheetId() !== sh.getSheetId()) return full;
  const start = Math.max(2, active.getRow());
  const end = Math.min(last, active.getLastRow());
  if (start > end) return full;
  return [start, end];
}

/**
 * Codes themes into CONFIG.outputCol. Called by cleanSurvey with an explicit sheet and
 * rows. Run alone (no arguments), it uses CONFIG.sheetName or the active sheet, and the
 * current selection if one is on that sheet.
 */
function autoCodeThemes(targetSheet, startRow, endRow) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sh = targetSheet ||
    (CONFIG.sheetName ? ss.getSheetByName(CONFIG.sheetName) : ss.getActiveSheet());
  if (!sh) throw new Error("Sheet not found: " + CONFIG.sheetName);

  const last = sh.getLastRow();
  if (last < 2) return;

  let start, end;
  if (startRow && endRow) {
    start = startRow;
    end = endRow;
  } else {
    [start, end] = targetRows_(ss, sh, last);
  }
  const count = end - start + 1;

  const patterns = buildThemePatterns_(CONFIG.mapping);
  const texts = sh.getRange(start, CONFIG.textCol, count, 1).getValues();
  const existing = sh.getRange(start, CONFIG.outputCol, count, 1).getValues();

  let written = 0;
  const tags = texts.map(([t], i) => {
    const current = existing[i][0];
    if (!CONFIG.forceOverwrite && String(current).trim() !== "") return [current];
    written++;
    return [tagThemes_(t, patterns)];
  });

  // Write header only if the output header cell is empty
  const headerCell = sh.getRange(1, CONFIG.outputCol);
  if (headerCell.getValue() === "") headerCell.setValue(CONFIG.outputHeader);

  sh.getRange(start, CONFIG.outputCol, count, 1).setValues(tags);
  ss.toast(
    "Rows " + start + "-" + end + ": coded " + written + ", kept " + (count - written) +
    " existing (set forceOverwrite to replace)",
    "Themes", 5
  );
}
```

**What changed:**
1. **Single file:** Cleanup, menu, permissions, and the theme coder are in one script. The config for both (`allowedEditors`, `PROTECTION_DESC`, and `CONFIG`) is at the top.
2. **Coder call:** After cleanup finishes (formulas, formatting, protection, ParkMap), `cleanSurvey` calls `autoCodeThemes(sh, 2, n)`. It passes the sheet and rows explicitly, so it codes the sheet cleanup just ran on, even if the selection is elsewhere.
3. **Skip when empty:** `hasTextResponses_` checks whether any row in the text column has a non-empty value. If none do, the coder is not called and nothing is shown.
4. **forceOverwrite:** Still respected inside the coder. With the default `false`, non-empty Themes cells are kept on re-runs.

**Things to know:**
- `CONFIG.sheetName` doesn't affect cleanup, which always works on the active sheet. It only applies when you run `autoCodeThemes()` on its own.
- The Themes column (Q) sits outside G:P, so it isn't protected and volunteers can still edit it. If you want it protected too, change `outputCol` and add its range to the protection.
- The confirm dialog still says "overwrite helper columns G:P". It doesn't mention Themes. Update the text if you want it to.

