function protectedA1_(lastRow) {
  return "G2:" + protectedEndLetter_() + lastRow;
}

/** Sheet-qualified range label for messages, e.g. "Sheet1 G2:Q123". */
function rangeLabel_(sh, a1) {
  return sh.getName() + " " + a1;
}

