// Helper columns written by cleanSurvey: G (7) through P (16)
const HELPER_FIRST_COL = 7;
const HELPER_LAST_COL = 16;

// ============================= MENU =============================

/** Adds a "Cleanup" menu to the sheet UI on open. */
function onOpen() {
