// ============================= HELPERS =============================

/** Converts a 1-based column number to A1 letters (1 -> A, 17 -> Q). */
function colToLetter_(c) {
  let s = "";
  while (c > 0) {
    const m = (c - 1) % 26;
    s = String.fromCharCode(65 + m) + s;
    c = Math.floor((c - 1) / 26);
  }
  return s;
}

/** Last protected column number: P, or the Themes column if protectThemes is true. */
