// ============================= CLEANUP =============================

function cleanSurvey() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const ui = SpreadsheetApp.getUi();
  const sh = ss.getActiveSheet();
  const n = sh.getLastRow();
  if (n < 2) {
    ui.alert("Cleanup", "No data rows found — nothing to do.", ui.ButtonSet.OK);
    return;
  }

  // Runtime values for protection and messages
  const endLetter = protectedEndLetter_();
  const desc = protectionDesc_(sh);
  const oldDesc = legacyProtectionDesc_();

  const canManage = canManageProtection(ss);

  // Protected range: G2:P<n>, or G2:Q<n> when protectThemes is true
  const protectA1 = protectedA1_(n);
  const protectLabel = rangeLabel_(sh, protectA1);

  // Remove protections on this sheet with the exact range whose description is the
  // sheet-qualified one, the legacy one, or empty/null (e.g. created manually)
  if (canManage) {
    try {
      sh.getProtections(SpreadsheetApp.ProtectionType.RANGE)
        .filter(p => {
          const d = p.getDescription();
          const descMatch = !d || d === desc || d === oldDesc;
          return descMatch &&
                 p.getRange().getSheet().getSheetId() === sh.getSheetId() &&
                 p.getRange().getA1Notation() === protectA1;
        })
        .forEach(p => p.remove());
    } catch (err) {
      ss.toast("Could not remove old protection for " + protectLabel + ": " + err.message, "Cleanup", 5);
    }
  }

  // Helper headers, one column at a time so the Themes column is skipped when protectThemes is on
  const headers = [
    "Yes/No", "Phone", "Timestamp (clean)", "Park (canonical)", "Email key",
    "Name key", "DUP-email", "DUP-name-time", "SUPERSEDED", "REVIEW/OK"
  ];
  const formulaCols = [];
  for (let c = HELPER_FIRST_COL; c <= HELPER_LAST_COL; c++) {
    if (!isWritableHelperCol_(c)) continue;
    formulaCols.push(c);
  }

  // Clear old helper data (rows 2..n) for writable columns only
  formulaCols.forEach(c => sh.getRange(2, c, n - 1, 1).clearContent());

  // Write headers and bold/center them
  formulaCols.forEach(c => {
    sh.getRange(1, c).setValue(headers[c - HELPER_FIRST_COL])
      .setFontWeight("bold").setHorizontalAlignment("center");
  });

  // Write formulas column by column
  const rows = [];
  for (let r = 2; r <= n; r++) rows.push(rowFormulas(r, n));
  formulaCols.forEach(c => {
    const colFormulas = rows.map(row => [row[c - HELPER_FIRST_COL]]);
    sh.getRange(2, c, n - 1, 1).setFormulas(colFormulas);
  });

  // Formatting (applied after formulas are written so the formulas still evaluate)
  if (isWritableHelperCol_(8)) sh.getRange(2, 8, n - 1, 1).setNumberFormat("@");                // H: Phone as plain text
  if (isWritableHelperCol_(9)) sh.getRange(2, 9, n - 1, 1).setNumberFormat("yyyy-mm-dd hh:mm"); // I: Datetime
  sh.autoResizeColumns(HELPER_FIRST_COL, HELPER_LAST_COL - HELPER_FIRST_COL + 1);               // G:P

  // Freeze header row on the active sheet
  sh.setFrozenRows(1);

  // Apply protection to protectA1: owner, allowedEditors, and the runner if listed
  if (canManage) {
    try {
      const prot = sh.getRange(protectA1).protect().setDescription(desc);
      prot.removeEditors(prot.getEditors());

      const emails = allowedEditors.map(e => String(e).trim()).filter(e => e);

      // Explicitly add the owner so they always keep access
      const owner = ss.getOwner();
      if (owner) emails.push(owner.getEmail());

      // Explicitly add the runner so they can unprotect later (if listed)
      const runner = currentUserEmail();
      if (runner && allowedEditors.some(e => String(e).trim().toLowerCase() === runner)) {
        emails.push(runner);
      }

      // Normalize to lowercase and dedupe
      const uniq = [...new Set(emails.map(e => e.toLowerCase()).filter(e => e))];
      const added = [];
      const failed = [];
      uniq.forEach(e => {
        try { prot.addEditor(e); added.push(e); } catch (err) { failed.push(e); }
      });
      added.sort();
      failed.sort();

      const dataRows = n - 1;
      let msg = "Protected " + protectLabel +
                " (rows 2-" + n + " — " + dataRows + " rows) — editors: " +
                (added.join(", ") || "none") +
                " (" + added.length + " added, " + failed.length + " failed)";
      if (failed.length) msg += " | Failed: " + failed.join(", ");
      ss.toast(msg, "Cleanup", 5);

      if (failed.length) {
        ui.alert(
          "Some editors could not be added",
          "These emails were not added to protection:\n\n" + failed.join("\n") +
          "\n\nCheck the addresses and that each is a Google account.",
          ui.ButtonSet.OK
        );
      }
    } catch (err) {
      ss.toast("Could not apply protection to " + protectLabel + ": " + err.message, "Cleanup", 5);
    }
  } else {
    ui.alert(
      "Protection skipped",
      "You are not the sheet owner or in allowedEditors, so the helper columns " +
      protectLabel + " were not protected. " +
      "The cleanup formulas were still applied.\n\n" +
      "To protect these columns, run as the sheet owner or add your email to allowedEditors.",
      ui.ButtonSet.OK
    );
  }

  // Create ParkMap only if missing. Headers are written and formatted only on creation.
  if (!ss.getSheetByName("ParkMap")) {
    const pm = ss.insertSheet("ParkMap");
    pm.getRange(1, 1, 1, 2).setValues([["Key", "Canonical"]])
      .setFontWeight("bold").setHorizontalAlignment("center");
    pm.setFrozenRows(1);
  }

  // Auto-code themes on the active sheet, only if there is at least one non-empty response.
  // If the Themes column is protected, only run when the runner can manage protection.
  // Otherwise skip, and toast only when notifyOnSkipThemes is true.
  if (!hasTextResponses_(sh, n)) return;

  if (protectThemes && !canManage) {
    if (notifyOnSkipThemes) {
      ss.toast("Themes coding skipped — no permission to write protected range " + protectLabel,
               "Cleanup", 5);
    }
    return;
  }

  const [start, end] = targetRows_(ss, sh, n);
  autoCodeThemes(sh, start, end);
}

function rowFormulas(r, n) {
  const yn = `TRIM(D${r})`;
  const phoneNorm = String.raw`REGEXREPLACE(REGEXREPLACE(TRIM(E${r}),"\D",""),"^1(\d{10})$","$1")`;
  return [
    // G: Yes/No
    String.raw`=IF(${yn}="","REVIEW",IF(REGEXMATCH(LOWER(${yn}),"^y(es)?$"),"Yes",IF(REGEXMATCH(LOWER(${yn}),"^no?$"),"No","REVIEW")))`,
    // H: Phone (no LET)
    String.raw`=IF(REGEXMATCH(${phoneNorm},"^\d{10}$"),REGEXREPLACE(${phoneNorm},"^(\d{3})(\d{3})(\d{4})$","($1) $2-$3"),"REVIEW")`,
    // I: Timestamp
    `=IF(ISNUMBER(A${r}),A${r},IFERROR(DATEVALUE(TRIM(A${r}))+IFERROR(TIMEVALUE(TRIM(A${r})),0),"REVIEW"))`,
    // J: Park canonical
    `=IF(TRIM(F${r})="","REVIEW",IFERROR(VLOOKUP(${parkKey(`F${r}`)},ParkMap!$A:$B,2,FALSE),"REVIEW"))`,
    // K: Email key
    `=LOWER(TRIM(C${r}))`,
    // L: Name key
    String.raw`=LOWER(TRIM(REGEXREPLACE(B${r},"\s+"," ")))`,
    // M: DUP-email
    `=IF(K${r}="","",IF(COUNTIF($K$2:$K$${n},K${r})>1,"DUP-email",""))`,
    // N: DUP-name-time (±10 min)
    `=IF(OR(L${r}="",NOT(ISNUMBER(I${r}))),"",IF(COUNTIFS($L$2:$L$${n},L${r},$I$2:$I$${n},">="&(I${r}-10/1440),$I$2:$I$${n},"<="&(I${r}+10/1440))>1,"DUP-name-time",""))`,
    // O: SUPERSEDED (keep earliest per email)
    `=IF(OR(K${r}="",NOT(ISNUMBER(I${r}))),"",IF(COUNTIFS($K$2:$K$${n},K${r},$I$2:$I$${n},"<"&I${r})+COUNTIFS($K$2:K${r},K${r},$I$2:I${r},I${r})>1,"SUPERSEDED",""))`,
    // P: REVIEW/OK
    `=IF(OR(G${r}="REVIEW",H${r}="REVIEW",I${r}="REVIEW",J${r}="REVIEW",M${r}<>"",N${r}<>""),"REVIEW","OK")`
  ];
}

function parkKey(c) {
  return String.raw`REGEXREPLACE(REGEXREPLACE(REGEXREPLACE(REGEXREPLACE(REGEXREPLACE(REGEXREPLACE(REGEXREPLACE(LOWER(${c}),"\bw\b","west"),"\be\b","east"),"\bn\b","north"),"\bs\b","south"),"pk\b","park"),"boro\b","borough"),"[^a-z]","")`;
}

// ============================= THEME CODER =============================

/** True if any data row in the text column has a non-empty response. */
function hasTextResponses_(sh, last) {
  if (last < 2) return false;
  const vals = sh.getRange(2, CONFIG.textCol, last - 1, 1).getValues();
  return vals.some(([v]) => String(v).trim() !== "");
}

/** Escapes regex special characters in a keyword. */
function escapeRegex_(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Builds { theme: [RegExp, ...] } with word boundaries and common suffixes. */
function buildThemePatterns_(mapping) {
  const patterns = {};
  Object.keys(mapping).forEach(theme => {
    patterns[theme] = mapping[theme].map(kw => {
      const k = escapeRegex_(String(kw).trim().toLowerCase());
      return new RegExp("\\b" + k + "(?:s|es|ed|ing|ly|er|ers)?\\b");
    });
  });
  return patterns;
}

/** Returns sorted, deduped, lowercase theme tags for one response, or "" if blank. */
function tagThemes_(text, patterns) {
  const t = String(text || "").trim().toLowerCase();
  if (!t) return "";
  const found = new Set();
  Object.keys(patterns).forEach(theme => {
    if (patterns[theme].some(re => re.test(t))) found.add(theme.toLowerCase());
  });
  if (found.size === 0) return CONFIG.otherLabel;
  return [...found].sort().join(", ");
}

/** Returns [startRow, endRow] from the selection on sh, or the full data range (2..last). */
function targetRows_(ss, sh, last) {
  const full = [2, last];
  const active = ss.getActiveRange();
  if (!active || active.getSheet().getSheetId() !== sh.getSheetId()) return full;
  const start = Math.max(2, active.getRow());
  const end = Math.min(last, active.getLastRow());
  if (start > end) return full;
  return [start, end];
}

/**
 * Codes themes into CONFIG.outputCol. Called by cleanSurvey with an explicit sheet and
 * rows. Run alone (no arguments), it uses CONFIG.sheetName or the active sheet, and the
 * current selection if one is on that sheet.
 */
function autoCodeThemes(targetSheet, startRow, endRow) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sh = targetSheet ||
    (CONFIG.sheetName ? ss.getSheetByName(CONFIG.sheetName) : ss.getActiveSheet());
  if (!sh) throw new Error("Sheet not found: " + CONFIG.sheetName);

  const last = sh.getLastRow();
  if (last < 2) return;

  let start, end;
  if (startRow && endRow) {
    start = startRow;
    end = endRow;
  } else {
    [start, end] = targetRows_(ss, sh, last);
  }
  const count = end - start + 1;

  const patterns = buildThemePatterns_(CONFIG.mapping);
  const texts = sh.getRange(start, CONFIG.textCol, count, 1).getValues();
  const existing = sh.getRange(start, CONFIG.outputCol, count, 1).getValues();

  let written = 0;
  const tags = texts.map(([t], i) => {
    const current = existing[i][0];
    if (!CONFIG.forceOverwrite && String(current).trim() !== "") return [current];
    written++;
    return [tagThemes_(t, patterns)];
  });

  // Write header only if the output header cell is empty; bold and center only when written
  const headerCell = sh.getRange(1, CONFIG.outputCol);
  if (headerCell.getValue() === "") {
    headerCell.setValue(CONFIG.outputHeader)
      .setFontWeight("bold").setHorizontalAlignment("center");
  }

  sh.getRange(start, CONFIG.outputCol, count, 1).setValues(tags);
  ss.toast(
    "Rows " + start + "-" + end + ": coded " + written + ", kept " + (count - written) +
    " existing (set forceOverwrite to replace)",
    "Themes", 5
  );
}
```

**What changed:**
- The removal filter now matches a protection if its description is empty or null (`!d`), equals `desc`, or equals `oldDesc`.

