  sheetName: "",          // "" = active sheet (cleanSurvey always uses the sheet it runs on)
  textCol: 2,             // open-ended column (B)
  outputCol: 17,          // helper output column (Q)
  outputHeader: "Themes",
  otherLabel: "other",
  forceOverwrite: false,  // true = overwrite non-empty output cells
  mapping: {
    trash: ["trash", "bin", "litter"],
    amenities: ["bench", "water", "signage", "dog", "mulch"],
    safety: ["light", "safety", "parking"],
    positive: ["great", "loved", "friendly", "love", "enjoy"]
  }
};

// Helper columns written by cleanSurvey: G (7) through P (16)
const HELPER_FIRST_COL = 7;
const HELPER_LAST_COL = 16;

// ============================= MENU =============================

/** Adds a "Cleanup" menu to the sheet UI on open. */
function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("Cleanup")
    .addItem("Run cleanSurvey", "runCleanSurveyWithConfirm")
    .addToUi();
}

/** Menu entry point: shows the confirm dialog first; nothing else runs unless Yes. */
function runCleanSurveyWithConfirm() {
  const ui = SpreadsheetApp.getUi();
  const sh = SpreadsheetApp.getActiveSheet();
  const n = sh.getLastRow();
  // No data rows: let cleanSurvey show its own "nothing to do" alert
  if (n < 2) {
    cleanSurvey();
    return;
  }
  const answer = ui.alert(
    "Cleanup",
    "This will overwrite helper columns " + rangeLabel_(sh, protectedA1_(n)) + ". Continue?",
    ui.ButtonSet.YES_NO
  );
  if (answer === ui.Button.YES) cleanSurvey();
}

// ============================= PERMISSIONS =============================

/** Returns the active user's email in lowercase, or "" if unavailable. */
function currentUserEmail() {
  return (Session.getActiveUser().getEmail() || "").trim().toLowerCase();
}

/** True if the active user is the sheet owner or listed in allowedEditors. */
function canManageProtection(ss) {
  const me = currentUserEmail();
  if (!me) return false;
  const owner = ss.getOwner();
  if (owner && owner.getEmail().toLowerCase() === me) return true;
  return allowedEditors.some(e => String(e).trim().toLowerCase() === me);
}

// ============================= HELPERS =============================

/** Converts a 1-based column number to A1 letters (1 -> A, 17 -> Q). */
function colToLetter_(c) {
  let s = "";
  while (c > 0) {
    const m = (c - 1) % 26;
    s = String.fromCharCode(65 + m) + s;
    c = Math.floor((c - 1) / 26);
  }
  return s;
}

/** Last protected column number: P, or the Themes column if protectThemes is true. */
function protectedEndCol_() {
  return protectThemes ? Math.max(HELPER_LAST_COL, CONFIG.outputCol) : HELPER_LAST_COL;
}

/** Letter for the last protected column (P or Q). */
function protectedEndLetter_() {
  return colToLetter_(protectedEndCol_());
}

/**
 * Sheet-qualified protection description including the sheet ID, e.g.
 * "Sheet1 (id 123456) — Helper cols G:P". Used everywhere the description is set.
 */
function protectionDesc_(sh) {
  return sh.getName() + " (id " + sh.getSheetId() + ") — Helper cols G:" + protectedEndLetter_();
}

/**
 * Legacy descriptions, matched only when removing old protections; never set.
 * - sheetQualifiedNoIdDesc_: intermediate format, e.g. "Sheet1 — Helper cols G:P"
 * - legacyProtectionDesc_: original format, e.g. "Helper cols G:P"
 */
function sheetQualifiedNoIdDesc_(sh) {
  return sh.getName() + " — Helper cols G:" + protectedEndLetter_();
}

function legacyProtectionDesc_() {
  return "Helper cols G:" + protectedEndLetter_();
}

/** Protected A1 range for a given last data row, e.g. "G2:P123" or "G2:Q123". */
function protectedA1_(lastRow) {
  return "G2:" + protectedEndLetter_() + lastRow;
}

/** Sheet-qualified range label for messages, e.g. "Sheet1 G2:Q123". */
function rangeLabel_(sh, a1) {
  return sh.getName() + " " + a1;
}

/** True if a helper column should be written by cleanSurvey (skips Themes when protected). */
function isWritableHelperCol_(c) {
  return !(protectThemes && c === CONFIG.outputCol);
