```javascript
/**
 * Builds (or rebuilds) a "ThemeSummary" sheet counting responses per theme tag
 * from CONFIG.outputCol. Blank cells are ignored; comma-separated tags are split,
 * trimmed, and lowercased. Includes CONFIG.otherLabel. Safe to re-run.
 */
function buildThemeSummary() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const src = ss.getActiveSheet();
  const last = src.getLastRow();

  const counts = {};
  if (last >= 2) {
    const values = src.getRange(2, CONFIG.outputCol, last - 1, 1).getValues();
    values.forEach(([cell]) => {
      const raw = String(cell || "").trim();
      if (!raw) return;
      raw.split(",")
        .map(t => t.trim().toLowerCase())
        .filter(t => t)
        .forEach(t => { counts[t] = (counts[t] || 0) + 1; });
    });
  }

  const rows = Object.keys(counts)
    .map(theme => [theme, counts[theme]])
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));

  let sh = ss.getSheetByName("ThemeSummary");
  if (sh) {
    sh.clearContents();
    sh.clearFormats();
  } else {
    sh = ss.insertSheet("ThemeSummary");
  }

  sh.getRange(1, 1, 1, 2).setValues([["Theme", "Count"]])
    .setFontWeight("bold").setHorizontalAlignment("center");
  if (rows.length) sh.getRange(2, 1, rows.length, 2).setValues(rows);
  sh.setFrozenRows(1);
  sh.autoResizeColumns(1, 2);

  ss.toast("ThemeSummary: " + rows.length + " themes counted", "Themes", 5);
}
```

Notes:
- Run it from the sheet that has the Themes column. It reads `CONFIG.outputCol` on the active sheet.
- Counts are per tag, so a response tagged "trash, amenities" adds one to each theme.
- If you want it in the menu, add `.addItem("Build ThemeSummary", "buildThemeSummary")` to the `createMenu("Cleanup")` chain in `onOpen`.

