```javascript
/**
 * Builds (or rebuilds) a "ThemeSummary" sheet counting responses per theme tag
 * from CONFIG.outputCol. Reads the same sheet autoCodeThemes uses (CONFIG.sheetName
 * if set, otherwise the active sheet). Blank cells are ignored; comma-separated tags
 * are split, trimmed, and lowercased for counting. Theme names are shown in title case
 * (hyphenated and apostrophe words keep their punctuation, e.g. "Dog-Friendly",
 * "Owner's"), except CONFIG.otherLabel, which is shown exactly as configured.
 * Adds a Percentage column (Count / responses) and a final Total row. Safe to re-run.
 */
function buildThemeSummary() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const src = CONFIG.sheetName ? ss.getSheetByName(CONFIG.sheetName) : ss.getActiveSheet();
  if (!src) throw new Error("Sheet not found: " + CONFIG.sheetName);
  const last = src.getLastRow();

  const counts = {};
  let responses = 0;
  if (last >= 2) {
    const values = src.getRange(2, CONFIG.outputCol, last - 1, 1).getValues();
    values.forEach(([cell]) => {
      const raw = String(cell || "").trim();
      if (!raw) return;
      responses++;
      raw.split(",")
        .map(t => t.trim().toLowerCase())
        .filter(t => t)
        .forEach(t => { counts[t] = (counts[t] || 0) + 1; });
    });
  }

  // Display label: title case per word (letters after a hyphen or apostrophe are
  // capitalized too), except the configured other label shown exactly as set
  const otherKey = String(CONFIG.otherLabel || "").trim().toLowerCase();
  const displayName = key => {
    if (key === otherKey) return CONFIG.otherLabel;
    return key.replace(/[a-z]+/g, w => w.charAt(0).toUpperCase() + w.slice(1));
  };

  // Sort on the lowercase key with a case-insensitive locale compare, then build display rows
  const collator = new Intl.Collator("en", { sensitivity: "base" });
  const themeRows = Object.keys(counts)
    .sort((a, b) => counts[b] - counts[a] || collator.compare(a, b))
    .map(key => [displayName(key), counts[key], responses ? counts[key] / responses : 0]);

  // Total row: Count = total responses; percentage shown as 100.0%
  const rows = themeRows.concat([["Total", responses, 1]]);

  let sh = ss.getSheetByName("ThemeSummary");
  if (sh) {
    sh.clearContents();
    sh.clearFormats();
  } else {
    sh = ss.insertSheet("ThemeSummary");
  }

  sh.getRange(1, 1, 1, 3).setValues([["Theme", "Count", "Percentage"]])
    .setFontWeight("bold").setHorizontalAlignment("center");
  sh.getRange(2, 1, rows.length, 3).setValues(rows);
  sh.getRange(2, 3, rows.length, 1).setNumberFormat("0.0%");
  sh.getRange(rows.length + 1, 1, 1, 3).setFontWeight("bold");
  sh.setFrozenRows(1);
  sh.autoResizeColumns(1, 3);

  ss.toast("ThemeSummary: " + themeRows.length + " themes counted — " + responses + " responses",
           "Themes", 5);
}
```

Notes:
- The title-case regex capitalizes each run of letters, so it treats the letter after `-` or `'` as a new word. `dog-friendly` → `Dog-Friendly`, `owner's` → `Owner's`. Note the `'s` in `owner's` also becomes `S` if written as `owner'S`; the regex only uppercases the first letter of each run, so `'s` becomes `'S`. Since the input is lowercased, `owner's` displays as `Owner'S`. If you want `Owner's`, tell me and I'll adjust the regex to skip letters after an apostrophe.
- `Intl.Collator("en", { sensitivity: "base" })` gives case-insensitive ordering, so the sort doesn't depend on the lowercase key alone.

The fix: capitalize only the first letter of each run of letters that follows a start of string or a hyphen (or other non-apostrophe, non-letter boundary), and leave letters after an apostrophe lowercase. Using a regex that matches a word start that is not preceded by an apostrophe handles this.

